#include "distributedproject.h"
#include <QCoreApplication>
#include <QJsonArray>
#include <QDir>
#include <QDebug>
int main(int argc,char **argv){QCoreApplication app(argc,argv);try{Deployment::Require(argc==10,"Pass source-root output-root ECC-node data-node ECC-port supervisor-port callback-port data-port status-port");const QString source=argv[1],output=argv[2],eccNode=argv[3],dataNode=argv[4];HardwareDeploymentSetup setup;setup.experimentFile=source+"/config/backend-presets/pedestals-single-cobo.xcfg";setup.profileFile=source+"/config/backend-presets/pedestals-profile.json";setup.callbackAddress="127.0.0.1";setup.eccPort=QString(argv[5]).toInt();setup.supervisorPort=QString(argv[6]).toInt();setup.callbackPort=QString(argv[7]).toInt();setup.boards=HardwareSetupBoards(CompileHardwareSetupExperiment(setup.experimentFile,setup.profileFile));for(auto &board:setup.boards){board.address="192.0.2.230";board.nodeObject="CoBo";board.nodeName="Hardware";board.controlPort=46001;board.senderPort=46002;board.receiverAddress="127.0.0.1";board.dataPort=QString(argv[8]).toInt();board.statusPort=QString(argv[9]).toInt();board.descriptionFile=source+"/config/backend-presets/cobo-hardware.xcfg";}QMap<QString,QByteArray> files;const auto group=Deployment::CompileGroup(setup,"group1",eccNode,"127.0.0.1",QJsonArray{QJsonObject{{"id","data"},{"node_id",dataNode},{"address","127.0.0.1"},{"port",setup.supervisorPort},{"sender_ids",QJsonArray{"0"}}}},&files);const auto bundle=Deployment::BuildBundle("integration-project",QJsonArray{QJsonObject{{"id",eccNode}},QJsonObject{{"id",dataNode}}},QJsonArray{group},files);Deployment::PrivateDirectory(output);Deployment::PrivateDirectory(output+"/objects");Deployment::Write(output+"/manifest.json",Deployment::Json(bundle.manifest));for(auto it=bundle.objects.begin();it!=bundle.objects.end();++it)Deployment::Write(output+"/objects/"+it.key(),it.value(),true);qInfo()<<"Portable configuration fixture created; no hardware commands sent.";return 0;}catch(const std::exception &error){qCritical().noquote()<<error.what();return 1;}}
